    private TextStyle textStyle;

    @Before
    public void setUp() {
        textStyle = TextStyle.builder().setMaxWidth(20).setIndent(4).get();
    }

    @Test
    public void testPadWithCenterAlignment() {
        textStyle = TextStyle.builder()
                .setMaxWidth(20)
                .setIndent(0)
                .setAlignment(Alignment.CENTER)
                .get();

        CharSequence result = textStyle.pad(false, "Hello");
        assertEquals(20, result.length());
        assertTrue(result.toString().contains("Hello"));
        // Check that "Hello" is centered (should have equal padding on both sides, +/- 1)
        String resultStr = result.toString();
        int helloIndex = resultStr.indexOf("Hello");
        int leftPadding = helloIndex;
        int rightPadding = resultStr.length() - (helloIndex + 5); // 5 is length of "Hello"
        assertTrue(Math.abs(leftPadding - rightPadding) <= 1);
    }

    @Test
    public void testPadWithLeftAlignment() {
        textStyle = TextStyle.builder()
                .setMaxWidth(20)
                .setIndent(4)
                .setAlignment(Alignment.LEFT)
                .get();

        CharSequence result = textStyle.pad(true, "Hello");
        assertEquals(20, result.length());
        assertTrue(result.toString().startsWith("    Hello")); // 4 spaces + Hello
    }

    @Test
    public void testPadWithRightAlignment() {
        textStyle = TextStyle.builder()
                .setMaxWidth(20)
                .setIndent(4)
                .setAlignment(Alignment.RIGHT)
                .get();

        CharSequence result = textStyle.pad(true, "Hello");
        assertEquals(20, result.length());
        assertTrue(result.toString().endsWith("Hello"));
        // Should have padding at the beginning
        String resultStr = result.toString();
        int helloIndex = resultStr.indexOf("Hello");
        assertEquals(15, helloIndex); // 20 total - 5 "Hello" = 15 spaces
    }

