        textStyle = TextStyle.builder()
                .setMaxWidth(20)
                .setIndent(4)
                .setAlignment(Alignment.LEFT)
                .get();

        CharSequence result = textStyle.pad(false, "Hello");
        assertEquals(20, result.length());
        assertTrue(result.toString().startsWith("Hello"));
        // No indent, so "Hello" should start at position 0
    }

