        textStyle = TextStyle.builder()
                .setMaxWidth(10)
                .setIndent(4)
                .setAlignment(Alignment.LEFT)
                .get();

        CharSequence result = textStyle.pad(true, "This text is too long");
        assertEquals("This text is too long", result.toString());
